#pragma once

// Lucent's logo in the application (ADR 0025).
//
// The build compiles the "app-icon" derivatives of the branding asset (assets/branding, generated by
// tools/branding/Update-Branding.ps1 from the logo's master) into the QML module as the Qt resource
// folder ":/lucent/branding/app-icon" (apps/lucent/CMakeLists.txt): one PNG per pixel size, each the
// same picture rendered for that size. Nothing here names a size or a file name: a new logo or a new
// size is a new version of the asset and needs no code change.
//
//   branding_icon()          the window icon: one QIcon with every image of the folder at its own
//                            size, which install_branding() makes the application's window icon
//                            (Windows asks for the small and the large icon at the display's scale).
//                            Lucent.exe's icon resource IDI_ICON1 is the same logo for the window
//                            class, Explorer and the taskbar.
//   BrandingImageProvider    the QML image provider "branding": image://branding/<role> is the
//                            role's image for the requested size (an Image's sourceSize times the
//                            window's device pixel ratio): the pre-rendered image of exactly that size
//                            when there is one (for the About dialog's 64-pixel logo at every scale
//                            from 100 to 300 %), otherwise the next larger one scaled down.
//
// Thread-safety: branding_images() and branding_image() read Qt resources and QImage only, on any
// thread (the provider may run on Qt Quick's image-loader thread). branding_icon() and
// install_branding() are for the UI thread, once the QGuiApplication exists.

#include <QIcon>
#include <QImage>
#include <QList>
#include <QQuickImageProvider>
#include <QSize>
#include <QString>

class QQmlEngine;

namespace lucent::ui {

// The role of the images the window icon and the About dialog's logo use (the resource folder
// :/lucent/branding/<role>).
inline constexpr char kBrandingAppIconRole[] = "app-icon";
// The image provider's id: QML loads "image://branding/<role>".
inline constexpr char kBrandingProviderId[] = "branding";

struct BrandingImage {
    QString path;  // ":/lucent/branding/<role>/<file name>"
    QSize size;    // pixels, read from the image's header
};

// The role's images in the resource, smallest first; none for a role the build did not compile in.
[[nodiscard]] QList<BrandingImage> branding_images(const QString& role);

// The role's image for a square of `requested` pixels (the larger side counts): the smallest image at
// least that large, scaled down (smoothly, aspect ratio kept) when it is larger; the largest image
// when none is that large (never scaled up); with no requested size (a non-positive side), the largest.
// A null image for an unknown role or an image that cannot be read.
[[nodiscard]] QImage branding_image(const QString& role, QSize requested);

// The application's window icon: every app-icon image at its own size.
[[nodiscard]] QIcon branding_icon();

// Serves image://branding/<role> (see the file comment).
class BrandingImageProvider final : public QQuickImageProvider {
public:
    BrandingImageProvider();

    QImage requestImage(const QString& id, QSize* size, const QSize& requested_size) override;
};

// Makes branding_icon() the application's window icon and registers a BrandingImageProvider with
// `engine` (which takes ownership) as kBrandingProviderId.
void install_branding(QQmlEngine& engine);

}  // namespace lucent::ui
